  "bioavailability_prediction": "low",
  "confidence": "high",
  "revision_action": "keep",
  "supportive_card_ids": ["C34","C18","C02","C17","C13","C31","C16","C07","C29","C70","C24","C111","C99","C100","C146","C188"],
  "contradictory_card_ids": ["C168","C183","C161","C180","C191"],
  "prediction_basis_card_ids": ["C34","C18","C02","C17","C13","C31","C16","C07","C29","C70","C24","C146","C188"],
  "claims": [
    {
      "claim": "L1/L2 gold-context records show absolute oral bioavailability below 20% for multiple transferable steroids: testosterone 3.6 ± 2.5%, testosterone undecanoate 6.8 ± 3.3%, abiraterone acetate <10% fasted, mometasone <1%, fulvestrant poor or not orally bioavailable, and thienorphine very low.",
      "card_ids": ["C34","C18","C02","C17","C13","C31","C16","C07","C29","C70","C24"]
    },
    {
      "claim": "L3 estradiol oral exposure is low, with Cmax 13.3 pg/mL after 0.625 mg Cenestin and 43.66 pg/mL after 2 mg estradiol/norgestimate, consistent with extensive first-pass loss for estradiol-like steroids.",
      "card_ids": ["C111","C99","C100"]
    },
    {
      "claim": "L4 estradiol solubility is very low, with qualitative water insolubility and apparent solubility 1.81 ± 0.19 µg/mL in buffer, supporting solubility-limited absorption for the estradiol-like query.",
      "card_ids": ["C146","C188"]
    },
    {
      "claim": "L4 testosterone Caco-2 permeability is high, with Papp 5.1 to 10.0 ×10^-5 cm/s and Pc 14.6 ×10^-5 cm/s, but testosterone itself has low absolute oral bioavailability of 3.6%, showing high permeability alone does not ensure F ≥ 20%.",
      "card_ids": ["C168","C183","C161","C180","C191","C34","C18"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C146","C188","C168","C183","C161","C180","C191"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule.",
    "The query D-ring modification with tertiary C17 hydroxyl and extra ring is not represented in any L4 record with measured bioavailability.",
    "L4 provides solubility and permeability data but not F values, so the F ≥ 20% threshold cannot be resolved directly.",
    "Transfer from estradiol low solubility versus testosterone high permeability is ambiguous because the query is not identical to either.",
    "No metabolism or clearance data for the query are available to assess first-pass loss."
  ],
  "decision_summary": "L4 adds low estradiol solubility and high testosterone permeability, but neither overturns the prior low decision. Direct low absolute oral bioavailability values from L1/L2 steroid contexts remain the strongest evidence, and high permeability is insufficient to establish F ≥ 20% given first-pass metabolism. The low prediction is kept with high confidence."
}

